1	/**
2	 * @module features/tv-dashboard/model/types
3	 *
4	 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
5	 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
6	 */
7	
8	/**
9	 * Canal de origem do dado de venda de uma unidade.
10	 *
11	 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
12	 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
13	 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
14	 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
15	 *   dia disponível em `historico_vendas` com selo "até DD/MM".
16	 * - `factory`: fábrica (sem venda; card de produção/expedição).
17	 */
18	export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';
19	
20	/** Estado RAG (red/amber/green) de um card de unidade. */
21	export type TvRagStatus = 'ok' | 'amber' | 'red';
22	
23	/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
24	export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';
25	
26	/** Severidade de uma exceção exibida na faixa inferior. */
27	export type TvExceptionSeverity = 'red' | 'amber';
28	
29	/** Tipo de exceção exibida na faixa inferior. */
30	export type TvExceptionKind =
31	  | 'stock-out'
32	  | 'stock-low'
33	  | 'no-movement'
34	  | 'stale-data';
35	
36	/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
37	export interface TvBusinessHours {
38	  start: number;
39	  end: number;
40	}
41	
42	/** Snapshot de vendas de uma unidade (live ou defasado). */
43	export interface TvSalesSnapshot {
44	  /** Valor vendido em R$ no dia de referência. */
45	  valor: number;
46	  /** Número de cupons/transações (null quando a fonte não informa). */
47	  cupons: number | null;
48	  /** Ticket médio em R$ (null quando a fonte não informa). */
49	  ticketMedio: number | null;
50	  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
51	  dataReferencia: string;
52	  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
53	  isLive: boolean;
54	  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
55	  caixaAberto: boolean | null;
56	  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
57	  atualizadoEm: string | null;
58	}
59	
60	/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
61	export interface TvStockAlertSummary {
62	  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
63	  zerados: number;
64	  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
65	  abaixoMinimo: number;
66	}
67	
68	/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
69	export interface TvStockAlertItem {
70	  produtoNome: string;
71	  quantidade: number;
72	  quantidadeMinima: number;
73	  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
74	  zerado: boolean;
75	}
76	
77	/** Heartbeat de movimentações de estoque de uma unidade no dia. */
78	export interface TvMovementSummary {
79	  /** Contagem de movimentações tipo `entrada` hoje. */
80	  entradas: number;
81	  /** Contagem de movimentações tipo `saida` hoje. */
82	  saidas: number;
83	  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
84	  ultimaBipagem: string | null;
85	}
86	
87	/** Dados de um card de loja no grid. */
88	export interface TvStoreData {
89	  lojaId: number;
90	  nome: string;
91	  channel: TvSalesChannel;
92	  /** Vendas do dia de referência (null quando não há dado disponível). */
93	  vendas: TvSalesSnapshot | null;
94	  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
95	  metaDia: number | null;
96	  /**
97	   * % da meta. Canal live = pró-rata da janela de funcionamento;
98	   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
99	   * null quando não há meta cadastrada ou fora da janela.
100	   */
101	  pctMeta: number | null;
102	  /** Delta % vs MESMO DIA da semana anterior (nunca "ontem"), ou null. */
103	  deltaSemana: number | null;
104	  estoque: TvStockAlertSummary;
105	  movimentacao: TvMovementSummary;
106	  rag: TvRagStatus;
107	  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
108	  ragReasons: string[];
109	}
110	
111	/** Produção agregada da fábrica num dia. */
112	export interface TvFactoryProduction {
113	  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
114	  dataReferencia: string;
115	  /** Quantidade de produtos distintos produzidos. */
116	  itens: number;
117	  /** Soma das quantidades produzidas. */
118	  totalUnidades: number;
119	}
120	
121	/** Dados do card diferenciado da fábrica. */
122	export interface TvFactoryData {
123	  lojaId: number;
124	  nome: string;
125	  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
126	  producao: TvFactoryProduction | null;
127	  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
128	  expedicoes: TvMovementSummary;
129	  estoque: TvStockAlertSummary;
130	  rag: TvRagStatus;
131	  ragReasons: string[];
132	}
133	
134	/** Uma linha da faixa de exceções. */
135	export interface TvException {
136	  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
137	  id: string;
138	  kind: TvExceptionKind;
139	  severity: TvExceptionSeverity;
140	  lojaId: number | null;
141	  lojaNome: string | null;
142	  /** Mensagem pronta para exibição (pt-BR). */
143	  message: string;
144	  produtoNome?: string;
145	  quantidade?: number;
146	  quantidadeMinima?: number;
147	}
148	
149	/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
150	export interface TvExceptionsResult {
151	  items: TvException[];
152	  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
153	  overflowCount: number;
154	  /** Total de exceções antes do corte. */
155	  totalCount: number;
156	}
157	
158	/** Resumo da rede para o hero. */
159	export interface TvNetworkSummary {
160	  /**
161	   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
162	   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
163	   */
164	  vendasHoje: number;
165	  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
166	  metaDia: number | null;
167	  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
168	  pctMetaProRata: number | null;
169	  /** Delta % vs mesmo dia da semana passada (lojas live), ou null. */
170	  deltaSemana: number | null;
171	  /** Total de exceções vermelhas na rede (sem cap de exibição). */
172	  alertasCriticos: number;
173	  /** Quantidade de lojas com venda ao vivo. */
174	  lojasLive: number;
175	  /** Quantidade de lojas com dado defasado. */
176	  lojasDefasadas: number;
177	}
178	
179	/** Frescor de um dado-fonte. */
180	export interface TvSourceFreshness {
181	  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
182	  updatedAt: string | null;
183	  level: TvFreshnessLevel;
184	  /** Intervalo esperado de atualização (ms) usado na classificação. */
185	  expectedIntervalMs: number;
186	}
187	
188	/** Freshness consolidado dos dados exibidos na TV. */
189	export interface TvFreshness {
190	  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
191	  vendasLive: TvSourceFreshness;
192	  /** Estoque/alertas (polling 5min + Realtime). */
193	  estoque: TvSourceFreshness;
194	  /** Momento em que o snapshot foi montado (ISO). */
195	  geradoEm: string;
196	}
197

1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvException,
14	  TvExceptionsResult,
15	  TvFreshness,
16	  TvFreshnessLevel,
17	  TvRagStatus,
18	  TvStockAlertItem,
19	} from './types';
20	
21	// ─────────────────────────────────────────────────────────────────────────────
22	// Constantes de negócio
23	// ─────────────────────────────────────────────────────────────────────────────
24	
25	/**
26	 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
27	 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
28	 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
29	 */
30	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };
31	
32	/**
33	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
34	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
35	 */
36	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
37	
38	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
39	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
40	
41	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
42	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
43	
44	/**
45	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
46	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
47	 */
48	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
49	
50	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
51	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
52	
53	/** Máximo de linhas exibidas na faixa de exceções. */
54	export const TV_EXCEPTIONS_LIMIT = 7;
55	
56	// ─────────────────────────────────────────────────────────────────────────────
57	// Datas (helpers locais, sem dependência de timezone UTC)
58	// ─────────────────────────────────────────────────────────────────────────────
59	
60	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
61	export function toIsoDateLocal(d: Date): string {
62	  const y = d.getFullYear();
63	  const m = String(d.getMonth() + 1).padStart(2, '0');
64	  const day = String(d.getDate()).padStart(2, '0');
65	  return `${y}-${m}-${day}`;
66	}
67	
68	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
69	export function parseIsoDateLocal(iso: string): Date {
70	  const [y, m, d] = iso.split('-').map(Number);
71	  return new Date(y, (m ?? 1) - 1, d ?? 1);
72	}
73	
74	/** Soma `days` dias a uma data, retornando nova instância. */
75	export function addDays(d: Date, days: number): Date {
76	  const out = new Date(d);
77	  out.setDate(out.getDate() + days);
78	  return out;
79	}
80	
81	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
82	export function formatLaggedDateLabel(isoDate: string): string {
83	  const d = parseIsoDateLocal(isoDate);
84	  const dd = String(d.getDate()).padStart(2, '0');
85	  const mm = String(d.getMonth() + 1).padStart(2, '0');
86	  return `até ${dd}/${mm}`;
87	}
88	
89	/**
90	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
91	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
92	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
93	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
94	 */
95	export function parseBrDateTime(value: string | null | undefined): Date | null {
96	  if (!value) return null;
97	  const m = value.match(
98	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
99	  );
100	  if (m) {
101	    const [, dd, mm, yyyy, hh, mi, ss] = m;
102	    const month = Number(mm);
103	    const day = Number(dd);
104	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
105	    return new Date(
106	      Number(yyyy),
107	      month - 1,
108	      day,
109	      Number(hh),
110	      Number(mi),
111	      ss ? Number(ss) : 0,
112	    );
113	  }
114	  const fallback = new Date(value);
115	  return Number.isNaN(fallback.getTime()) ? null : fallback;
116	}
117	
118	// ─────────────────────────────────────────────────────────────────────────────
119	// Pró-rata da meta
120	// ─────────────────────────────────────────────────────────────────────────────
121	
122	/**
123	 * Fração linear do dia comercial já decorrida em `now`.
124	 *
125	 * - Antes da abertura → 0 (não há venda esperada ainda).
126	 * - Depois do fechamento → 1 (meta integral esperada).
127	 * - Dentro da janela → interpolação linear simples (pró-rata).
128	 */
129	export function businessDayFraction(
130	  now: Date,
131	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
132	): number {
133	  const { start, end } = hours;
134	  if (end <= start) {
135	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
136	    return now.getHours() >= end ? 1 : 0;
137	  }
138	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
139	  if (h <= start) return 0;
140	  if (h >= end) return 1;
141	  return (h - start) / (end - start);
142	}
143	
144	/**
145	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
146	 *
147	 * Retorna null quando não dá para calcular com honestidade:
148	 * - meta ausente/zerada (sem referência), ou
149	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
150	 */
151	export function pctOfProRataTarget(
152	  sold: number,
153	  dailyTarget: number | null | undefined,
154	  now: Date,
155	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
156	): number | null {
157	  if (dailyTarget == null || dailyTarget <= 0) return null;
158	  const fraction = businessDayFraction(now, hours);
159	  if (fraction <= 0) return null;
160	  return (sold / (dailyTarget * fraction)) * 100;
161	}
162	
163	/**
164	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
165	 * cujo dia de referência já encerrou.
166	 */
167	export function pctOfFullDayTarget(
168	  sold: number,
169	  dailyTarget: number | null | undefined,
170	): number | null {
171	  if (dailyTarget == null || dailyTarget <= 0) return null;
172	  return (sold / dailyTarget) * 100;
173	}
174	
175	// ─────────────────────────────────────────────────────────────────────────────
176	// Delta semanal
177	// ─────────────────────────────────────────────────────────────────────────────
178	
179	/**
180	 * Delta % vs MESMO DIA da semana anterior (nunca "ontem" — spec).
181	 * Retorna null quando a base de comparação é ausente ou não positiva.
182	 */
183	export function weekOverWeekDelta(
184	  current: number,
185	  lastWeek: number | null | undefined,
186	): number | null {
187	  if (lastWeek == null || lastWeek <= 0) return null;
188	  return ((current - lastWeek) / lastWeek) * 100;
189	}
190	
191	/**
192	 * Base PRÓ-RATEADA da semana passada para o delta do canal LIVE:
193	 * `lastWeek × businessDayFraction(now)` — o delta resultante compara hoje
194	 * (dia parcial) vs o MESMO PONTO do dia na semana passada, assumindo
195	 * distribuição intra-dia linear na janela (mesma fração usada no pró-rata
196	 * da meta, por consistência).
197	 *
198	 * Comparar dia parcial com dia completo inflava a queda de manhã.
199	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
200	 *
201	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
202	 * (fração 0 — não há ponto de comparação honesto).
203	 */
204	export function proRataLastWeekBase(
205	  lastWeek: number | null | undefined,
206	  now: Date,
207	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
208	): number | null {
209	  if (lastWeek == null || lastWeek <= 0) return null;
210	  const fraction = businessDayFraction(now, hours);
211	  if (fraction <= 0) return null;
212	  return lastWeek * fraction;
213	}
214	
215	// ─────────────────────────────────────────────────────────────────────────────
216	// RAG da loja
217	// ─────────────────────────────────────────────────────────────────────────────
218	
219	/** Entrada da classificação RAG de uma unidade. */
220	export interface StoreRagInput {
221	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
222	  stockOutCount: number;
223	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
224	  stockLowCount: number;
225	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
226	  pctMetaProRata: number | null;
227	  /** true quando a unidade tem venda ao vivo (canal Degust). */
228	  isLiveChannel: boolean;
229	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
230	  lastMovementAt: Date | string | null;
231	  /** Instante da avaliação. */
232	  now: Date;
233	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
234	  hours?: TvBusinessHours;
235	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
236	  noMovementThresholdHours?: number;
237	}
238	
239	/**
240	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
241	 *
242	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
243	 *   não faz sentido alertar madrugada sem bipagem.
244	 * - A referência é clampada ao início da janela de hoje: se a última
245	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
246	 */
247	export function hoursWithoutMovementInWindow(
248	  lastMovementAt: Date | string | null,
249	  now: Date,
250	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
251	): number | null {
252	  const fraction = businessDayFraction(now, hours);
253	  if (fraction <= 0 || fraction >= 1) return null;
254	  const windowStart = new Date(now);
255	  windowStart.setHours(hours.start, 0, 0, 0);
256	  const last = lastMovementAt
257	    ? new Date(lastMovementAt).getTime()
258	    : Number.NEGATIVE_INFINITY;
259	  const ref = Math.max(last, windowStart.getTime());
260	  return (now.getTime() - ref) / 3_600_000;
261	}
262	
263	/**
264	 * Classificação RAG de uma unidade (management-by-exception).
265	 *
266	 * Regras (design.md §1.6, ordem de precedência):
267	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
268	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
269	 *   manhã, quando o pró-rata ainda é instável).
270	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
271	 *   movimentação há mais que o threshold dentro da janela OU venda live com
272	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
273	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
274	 *   em canal live e com meta cadastrada (pct != null).
275	 * - OK: nenhum desvio — tela calma, sem cor.
276	 */
277	export function classifyStoreRag(input: StoreRagInput): {
278	  status: TvRagStatus;
279	  reasons: string[];
280	} {
281	  const hours = input.hours ?? TV_BUSINESS_HOURS;
282	  const noMovementThreshold =
283	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
284	  const reasons: string[] = [];
285	
286	  // ── Vermelho: só ruptura (item zerado em alerta) ──
287	  if (input.stockOutCount > 0) {
288	    reasons.push(
289	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
290	    );
291	    return { status: 'red', reasons };
292	  }
293	
294	  // ── Âmbar ──
295	  if (input.stockLowCount > 0) {
296	    reasons.push(
297	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
298	    );
299	  }
300	  const gapHours = hoursWithoutMovementInWindow(
301	    input.lastMovementAt,
302	    input.now,
303	    hours,
304	  );
305	  if (gapHours !== null && gapHours > noMovementThreshold) {
306	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
307	  }
308	  if (
309	    input.isLiveChannel &&
310	    input.pctMetaProRata !== null &&
311	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
312	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
313	  ) {
314	    reasons.push(
315	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
316	    );
317	  }
318	  if (reasons.length > 0) return { status: 'amber', reasons };
319	
320	  return { status: 'ok', reasons: [] };
321	}
322	
323	/** Entrada de {@link buildNoMovementException}. */
324	export interface NoMovementExceptionInput {
325	  lojaId: number;
326	  lojaNome: string;
327	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
328	  lastMovementAt: Date | string | null;
329	  now: Date;
330	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
331	  hours?: TvBusinessHours;
332	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
333	  thresholdHours?: number;
334	}
335	
336	/**
337	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
338	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
339	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
340	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
341	 * Retorna null quando não há gap acima do threshold dentro da janela.
342	 */
343	export function buildNoMovementException(
344	  input: NoMovementExceptionInput,
345	): TvException | null {
346	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
347	  const gap = hoursWithoutMovementInWindow(
348	    input.lastMovementAt,
349	    input.now,
350	    input.hours ?? TV_BUSINESS_HOURS,
351	  );
352	  if (gap === null || gap <= threshold) return null;
353	  return {
354	    id: `no-movement:${input.lojaId}`,
355	    kind: 'no-movement',
356	    severity: 'amber',
357	    lojaId: input.lojaId,
358	    lojaNome: input.lojaNome,
359	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
360	  };
361	}
