363	// ─────────────────────────────────────────────────────────────────────────────
364	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
365	// ─────────────────────────────────────────────────────────────────────────────
366	
367	function trimOneDecimal(v: number): string {
368	  const rounded = Math.round(v * 10) / 10;
369	  return rounded.toLocaleString('pt-BR', {
370	    minimumFractionDigits: 0,
371	    maximumFractionDigits: 1,
372	  });
373	}
374	
375	/**
376	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
377	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
378	 * Valores negativos preservam o sinal ("-R$ 1,2k").
379	 */
380	export function formatCompactBRL(value: number): string {
381	  const sign = value < 0 ? '-' : '';
382	  const abs = Math.abs(value);
383	  // Bump pra M quando o arredondamento em k chegaria a 1000k
384	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
385	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
386	  }
387	  if (abs >= 1_000) {
388	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
389	  }
390	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
391	}
