393	// ─────────────────────────────────────────────────────────────────────────────
394	// Staleness
395	// ─────────────────────────────────────────────────────────────────────────────
396	
397	/**
398	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
399	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
400	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
401	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
402	 */
403	export function classifyStaleness(
404	  lastUpdatedAt: Date | string | number | null | undefined,
405	  expectedIntervalMs: number,
406	  now: Date,
407	): TvFreshnessLevel {
408	  if (lastUpdatedAt == null) return 'very-stale';
409	  const ts = new Date(lastUpdatedAt).getTime();
410	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
411	  const age = now.getTime() - ts;
412	  if (age < 2 * expectedIntervalMs) return 'fresh';
413	  if (age < 6 * expectedIntervalMs) return 'stale';
414	  return 'very-stale';
415	}
416	
417	/**
418	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
419	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
420	 *
421	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
422	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
423	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
424	 * parar de avançar além de 2× o intervalo esperado.
425	 */
426	export function buildFreshness(
427	  liveUpdatedAtMs: number,
428	  stockUpdatedAtMs: number,
429	  intervals: { liveMs: number; slowMs: number },
430	  now: Date,
431	): TvFreshness {
432	  const liveUpdatedAt =
433	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
434	  const stockUpdatedAt =
435	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
436	  return {
437	    vendasLive: {
438	      updatedAt: liveUpdatedAt,
439	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
440	      expectedIntervalMs: intervals.liveMs,
441	    },
442	    estoque: {
443	      updatedAt: stockUpdatedAt,
444	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
445	      expectedIntervalMs: intervals.slowMs,
446	    },
447	    geradoEm: now.toISOString(),
448	  };
449	}
