451	// ─────────────────────────────────────────────────────────────────────────────
452	// Exceções — ordenação e corte
453	// ─────────────────────────────────────────────────────────────────────────────
454	
455	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
456	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
457	const KIND_ORDER: Record<string, number> = {
458	  'stock-out': 0,
459	  'stock-low': 1,
460	  'no-movement': 2,
461	  'stale-data': 3,
462	};
463	
464	/**
465	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
466	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
467	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
468	 * contagem do excedente.
469	 */
470	export function sortAndLimitExceptions(
471	  exceptions: TvException[],
472	  limit: number = TV_EXCEPTIONS_LIMIT,
473	): TvExceptionsResult {
474	  const sorted = [...exceptions].sort((a, b) => {
475	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
476	    if (sev !== 0) return sev;
477	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
478	    if (kind !== 0) return kind;
479	    return a.message.localeCompare(b.message, 'pt-BR');
480	  });
481	  return {
482	    items: sorted.slice(0, limit),
483	    overflowCount: Math.max(0, sorted.length - limit),
484	    totalCount: sorted.length,
485	  };
486	}
