506	/**
507	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
508	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
509	 * são ignoradas.
510	 */
511	export function aggregateMovements(
512	  rows: MovementRow[],
513	): Map<number, MovementAggregate> {
514	  const out = new Map<number, MovementAggregate>();
515	  for (const row of rows) {
516	    if (row.loja_id == null) continue;
517	    let agg = out.get(row.loja_id);
518	    if (!agg) {
519	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
520	      out.set(row.loja_id, agg);
521	    }
522	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
523	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
524	    if (
525	      row.data_movimentacao &&
526	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
527	    ) {
528	      agg.ultimaBipagem = row.data_movimentacao;
529	    }
530	  }
531	  return out;
532	}
