623	/**
624	 * Corrige o `loja_id` das linhas de flash-vendas.
625	 *
626	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
627	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
628	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
629	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
630	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
631	 *
632	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
633	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
634	 * - Caso contrário → descarta (não corromper outra loja).
635	 */
636	export function remapFlashLojaIds(
637	  rows: FlashRow[],
638	  degustCodeToLoja: ReadonlyMap<number, number>,
639	  knownDegustLojaIds: ReadonlySet<number>,
640	): FlashRow[] {
641	  const out: FlashRow[] = [];
642	  for (const row of rows) {
643	    if (knownDegustLojaIds.has(row.loja_id)) {
644	      out.push(row);
645	      continue;
646	    }
647	    const mapped = degustCodeToLoja.get(row.loja_id);
648	    if (mapped != null) {
649	      out.push({ ...row, loja_id: mapped });
650	    }
651	    // não mapeável → descartado de propósito (ver TSDoc)
652	  }
653	  return out;
654	}
