693	// ─────────────────────────────────────────────────────────────────────────────
694	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
695	// ─────────────────────────────────────────────────────────────────────────────
696	
697	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
698	export interface TvPageResult<T> {
699	  data: T[] | null;
700	  error: { message: string } | null;
701	}
702	
703	/**
704	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
705	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
706	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
707	 *
708	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
709	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
710	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
711	 * sobreporem entre requests.
712	 */
713	export async function fetchAllPages<T>(
714	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
715	  pageSize = 1000,
716	): Promise<T[]> {
717	  const all: T[] = [];
718	  let offset = 0;
719	  for (;;) {
720	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
721	    if (error) throw error;
722	    const rows = data ?? [];
723	    all.push(...rows);
724	    if (rows.length < pageSize) return all;
725	    offset += pageSize;
726	  }
727	}
