113	function isFactoryTipo(tipo: string | null): boolean {
114	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
115	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
116	}
