172	    loja_id: f.loja_id,
173	    nome_loja: f.nome_loja,
174	    total_vendas: f.total_vendas,
175	    total_cupons: f.total_cupons,
176	    ticket_medio: f.ticket_medio,
177	    caixa_aberto: f.caixa_aberto,
