183	// ─────────────────────────────────────────────────────────────────────────────
184	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
185	// ─────────────────────────────────────────────────────────────────────────────
186	
187	interface LaggedSales {
188	  lojaId: number;
189	  /** Último dia com venda registrada (YYYY-MM-DD). */
190	  dataReferencia: string;
191	  valor: number;
192	  quantidade: number;
193	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
194	  valorSemanaAnterior: number | null;
195	}
196	
197	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
198	  // 1) Último dia com dado para a loja
199	  const { data: latest, error: latestErr } = await supabase
200	    .from('historico_vendas')
201	    .select('data')
202	    .eq('loja_id', lojaId)
203	    .order('data', { ascending: false })
204	    .limit(1);
205	  if (latestErr) throw latestErr;
206	  const refDate = latest?.[0]?.data;
207	  if (!refDate) return null;
208	
209	  const prevDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
210	
211	  // 2) Vendas do dia de referência + mesmo dia da semana anterior
212	  const [curRes, prevRes] = await Promise.all([
213	    supabase
214	      .from('historico_vendas')
215	      .select('valor_total, quantidade')
216	      .eq('loja_id', lojaId)
217	      .eq('data', refDate)
218	      .limit(2000),
219	    supabase
220	      .from('historico_vendas')
221	      .select('valor_total')
222	      .eq('loja_id', lojaId)
223	      .eq('data', prevDate)
224	      .limit(2000),
225	  ]);
226	  if (curRes.error) throw curRes.error;
227	  if (prevRes.error) throw prevRes.error;
228	
229	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
230	  const quantidade = (curRes.data ?? []).reduce(
231	    (s, r) => s + (r.quantidade ?? 0),
232	    0,
233	  );
234	  const prevRows = prevRes.data ?? [];
235	  const valorSemanaAnterior =
236	    prevRows.length > 0
237	      ? prevRows.reduce((s, r) => s + (r.valor_total ?? 0), 0)
238	      : null;
239	
240	  return { lojaId, dataReferencia: refDate, valor, quantidade, valorSemanaAnterior };
241	}
242	
243	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
244	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
245	  return results.filter((r): r is LaggedSales => r !== null);
246	}
