249	// Comparativo Degust: mesmo dia da semana passada (degust_vendas_diarias)
250	// ─────────────────────────────────────────────────────────────────────────────
251	
252	async function fetchDegustLastWeek(ctx: TvContext): Promise<Map<number, number>> {
253	  const lastWeekDate = toIsoDateLocal(addDays(new Date(), -7));
254	  const ids = [...ctx.degustLojaIds];
255	  const out = new Map<number, number>();
256	  if (ids.length === 0) return out;
257	  const { data, error } = await supabase
258	    .from('degust_vendas_diarias')
259	    .select('loja_id, valor_total')
260	    .eq('data', lastWeekDate)
261	    .in('loja_id', ids)
262	    .limit(5000);
263	  if (error) throw error;
264	  for (const row of data ?? []) {
265	    out.set(row.loja_id, (out.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
266	  }
267	  return out;
268	}
