287	function metaFor(
288	  metas: Map<string, number> | undefined,
289	  lojaId: number,
290	  date: Date,
291	): number | null {
292	  if (!metas) return null;
293	  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
