296	// ─────────────────────────────────────────────────────────────────────────────
297	// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
298	// ─────────────────────────────────────────────────────────────────────────────
299	
300	async function fetchStockAlerts(): Promise<StockRow[]> {
301	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
302	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
303	  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
304	  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
305	  const data = await fetchAllPages((from, to) =>
306	    supabase
307	      .from('estoque')
308	      .select(
309	        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo)',
310	      )
311	      .eq('produto_master.ativo', true)
312	      .gt('quantidade_minima', 0)
313	      .or('oculto.is.null,oculto.eq.false')
314	      .order('id')
315	      .range(from, to),
316	  );
317	  return data.map((row) => ({
318	    loja_id: row.loja_id,
319	    quantidade_atual: row.quantidade_atual,
320	    quantidade_minima: row.quantidade_minima,
321	    produtoNome: row.produto_master?.nome ?? '(sem nome)',
322	  }));
323	}
