326	// Movimentações de hoje (heartbeat por loja)
327	// ─────────────────────────────────────────────────────────────────────────────
328	
329	async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
330	  const startOfDay = new Date();
331	  startOfDay.setHours(0, 0, 0, 0);
332	  // Pico real >1k movimentações/dia: paginar (PostgREST corta em 1000).
333	  const data = await fetchAllPages((from, to) =>
334	    supabase
335	      .from('movimentacoes')
336	      .select('loja_id, tipo_movimentacao, data_movimentacao')
337	      .gte('data_movimentacao', startOfDay.toISOString())
338	      .order('id')
339	      .range(from, to),
340	  );
341	  return aggregateMovements(data);
342	}
