344	// ─────────────────────────────────────────────────────────────────────────────
345	// Produção da fábrica (daily_production com loja_id NULL = fábrica)
346	// ─────────────────────────────────────────────────────────────────────────────
347	
348	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
349	  const today = toIsoDateLocal(new Date());
350	
351	  const loadDay = async (date: string) => {
352	    const { data, error } = await supabase
353	      .from('daily_production')
354	      .select('quantity')
355	      .is('loja_id', null)
356	      .eq('date', date)
357	      .limit(2000);
358	    if (error) throw error;
359	    return data ?? [];
360	  };
361	
362	  let refDate = today;
363	  let rows = await loadDay(today);
364	  if (rows.length === 0) {
365	    // Sem produção registrada hoje → mostra o último dia disponível
366	    const { data: latest, error } = await supabase
367	      .from('daily_production')
368	      .select('date')
369	      .is('loja_id', null)
370	      .lte('date', today)
371	      .order('date', { ascending: false })
372	      .limit(1);
373	    if (error) throw error;
374	    const lastDate = latest?.[0]?.date;
375	    if (!lastDate) return null;
376	    refDate = lastDate;
377	    rows = await loadDay(lastDate);
378	  }
379	
380	  return {
381	    dataReferencia: refDate,
382	    itens: rows.length,
383	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
384	  };
385	}
