388	// Top produtos do dia da rede (degust_vendas_diarias, SOMENTE hoje)
389	// ─────────────────────────────────────────────────────────────────────────────
390	
391	async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
392	  const ids = [...ctx.degustLojaIds];
393	  if (ids.length === 0) return [];
394	  // O card é rotulado "TOP 5 PRODUTOS · HOJE": filtra `data` = hoje no fuso
395	  // LOCAL (mesmo `toIsoDateLocal` usado no resto do hook). Sem vendas hoje →
396	  // lista vazia (a UI mostra "aguardando vendas do dia"); nunca mostrar
397	  // ontem com rótulo de hoje.
398	  const today = toIsoDateLocal(new Date());
399	  const data = await fetchAllPages((from, to) =>
400	    supabase
401	      .from('degust_vendas_diarias')
402	      .select('degust_nome, quantidade, valor_total')
403	      .eq('data', today)
404	      .in('loja_id', ids)
405	      .order('id')
406	      .range(from, to),
407	  );
408	  return topProductsFromDaily(data, 5);
409	}
