/** Estado RAG (red/amber/green) de um card de unidade. */
export type TvRagStatus = 'ok' | 'amber' | 'red';

/**
 * Filtro global de período do painel (v3): hoje / semana corrente
 * (segunda→hoje) / mês corrente (dia 1º→hoje). Perdas, compras e seus
 * comparativos respeitam o filtro; vendas dos cards são SEMPRE de hoje.
 */
export type TvPeriod = 'today' | 'week' | 'month';

/** Range de dias FECHADO [from, to], ambos YYYY-MM-DD no fuso local. */
export interface TvDateRange {
  from: string;
  to: string;
}

/** Severidade de um item de estoque crítico (zerado pesa mais). */
export type TvCriticalSeverity = 'zerado' | 'abaixo-minimo';

/**
 * Item de estoque crítico NOMEADO de uma unidade, já ordenável por
 * severidade (zerados ⛔ primeiro; depois ⚠ por % faltante).
 */
export interface TvCriticalItem {
  nome: string;
  quantidade: number;
  minima: number;
  severity: TvCriticalSeverity;
}

/** Linha do feed de movimentações nomeado ("AGORA" / drill-down). */
export interface TvRecentMove {
  /** Hora local HH:mm derivada de `data_movimentacao` ("—" se ausente). */
  hora: string;
  /** Timestamp cru ISO da movimentação (ordenar/tooltip), ou null. */
  timestamp: string | null;
  /** Tipo cru (`entrada` | `saida` | outros valores da tabela). */
  tipo: string;
  produtoNome: string;
  quantidade: number;
}

/** Perdas agregadas (tabela `perdas`) no período do filtro global. */
export interface TvPerdasSummary {
  /** R$ somado de `valor_estimado` (linhas sem valor contam como 0). */
  valor: number;
  /** Número de registros de perda no período. */
  itens: number;
  /** Delta % vs período anterior equivalente (null sem base positiva). */
  deltaPct: number | null;
}

/** Compras (NFs `notas_fiscais`) agregadas no período do filtro global. */
export interface TvComprasSummary {
  /** R$ somado de `valor_total` com status válido (≠ erro). */
  valor: number;
  /** Delta % vs período anterior equivalente (null sem base positiva). */
  deltaPct: number | null;
}

/** Linha detalhada de perda (drill-down por loja). */
export interface TvPerdaDetail {
  id: number;
  produtoNome: string;
  quantidade: number;
  unidade: string | null;
  motivo: string;
  /** R$ estimado da perda (0 quando não informado). */
  valor: number;
  /** Timestamp ISO de `data_identificacao`, ou null. */
  data: string | null;
}

/** Linha detalhada de NF de compra (drill-down por loja). */
export interface TvNotaFiscalDetail {
  id: number;
  numero: string;
  fornecedor: string;
  valor: number;
  /** Data de emissão `data_nota` (YYYY-MM-DD — campo canônico no app). */
  dataNota: string;
}

