/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
export function timeHHMMFromIso(iso: string | null | undefined): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
 * - `today`: hoje → hoje;
 * - `week`: segunda-feira da semana corrente → hoje;
 * - `month`: dia 1º do mês corrente → hoje.
 */
export function periodRange(period: TvPeriod, now: Date): TvDateRange {
  const today = toIsoDateLocal(now);
  if (period === 'today') return { from: today, to: today };
  if (period === 'week') {
    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
    const dowFromMonday = (now.getDay() + 6) % 7;
    const monday = addDays(now, -dowFromMonday);
    return { from: toIsoDateLocal(monday), to: today };
  }
  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  return { from: toIsoDateLocal(firstOfMonth), to: today };
}

/**
 * Período ANTERIOR equivalente para comparativos do filtro global:
 * - `today`: ontem → ontem;
 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
 */
export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
  if (period === 'today') {
    const yesterday = toIsoDateLocal(addDays(now, -1));
    return { from: yesterday, to: yesterday };
  }
  if (period === 'week') {
    const dowFromMonday = (now.getDay() + 6) % 7;
    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
    return {
      from: toIsoDateLocal(mondayLastWeek),
      to: toIsoDateLocal(addDays(now, -7)),
    };
  }
  const y = now.getFullYear();
  const m = now.getMonth();
  const firstPrev = new Date(y, m - 1, 1);
  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
  const lastDayPrevMonth = new Date(y, m, 0).getDate();
  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
}

/**
 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
 */
export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
  const from = parseIsoDateLocal(range.from);
  const to = parseIsoDateLocal(range.to);
  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
  return {
    from: toIsoDateLocal(addDays(from, -days)),
    to: toIsoDateLocal(addDays(to, -days)),
  };
}

/**
 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
 * (exclusivo — usar `.lt`, nunca `.lte`).
 */
export function rangeToLocalDayBounds(range: TvDateRange): {
  startIso: string;
  endExclusiveIso: string;
} {
  const start = parseIsoDateLocal(range.from);
  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
  return {
    startIso: start.toISOString(),
    endExclusiveIso: endExclusive.toISOString(),
  };
}

