// ─────────────────────────────────────────────────────────────────────────────
// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
 * passada, período anterior do filtro…). Retorna null quando a base é
 * ausente ou não positiva — sem base honesta, sem número inventado.
 */
export function relativeDelta(
  current: number,
  base: number | null | undefined,
): number | null {
  if (base == null || base <= 0) return null;
  return ((current - base) / base) * 100;
}

/**
 * Delta % vs MESMO DIA da semana anterior — caso particular de
 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
 */
export function weekOverWeekDelta(
  current: number,
  lastWeek: number | null | undefined,
): number | null {
  return relativeDelta(current, lastWeek);
}

/**
 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
 * usada no pró-rata da meta, por consistência).
 *
 * Comparar dia parcial com dia completo inflava a queda de manhã.
 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
 *
 * Retorna null quando a base é ausente/não positiva ou antes da abertura
 * (fração 0 — não há ponto de comparação honesto).
 */
export function proRataDayBase(
  referenceDayTotal: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0) return null;
  return referenceDayTotal * fraction;
}

/**
 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
 * a API existente).
 */
export function proRataLastWeekBase(
  lastWeek: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  return proRataDayBase(lastWeek, now, hours);
}

/**
 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
 * o drill-down, a lista completa.
 */
export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
  const missingFraction = (c: TvCriticalItem): number =>
    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
  return items
    .map<TvCriticalItem>((i) => ({
      nome: i.produtoNome,
      quantidade: i.quantidade,
      minima: i.quantidadeMinima,
      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
    }))
    .sort((a, b) => {
      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
      const diff = missingFraction(b) - missingFraction(a);
      if (diff !== 0) return diff;
      return a.nome.localeCompare(b.nome, 'pt-BR');
    });
}

/** Linha mínima de `perdas` necessária à agregação por loja/rede. */
export interface PerdaAggRow {
  loja_id: number | null;
  valor_estimado: number | null;
}

/** Perdas agregadas (R$ + nº de registros). */
export interface PerdasAggregate {
  valor: number;
  itens: number;
}

/** Resultado da agregação de perdas: por loja + total da rede. */
export interface PerdasByLoja {
  byLoja: Map<number, PerdasAggregate>;
  /** Total da REDE — inclui linhas sem loja_id (fora de qualquer coluna). */
  total: PerdasAggregate;
}

/**
 * Agrega perdas do período: R$ (soma de `valor_estimado`, nulls contam 0 —
 * a perda EXISTE mesmo sem valor estimado e entra na contagem de itens) e
 * nº de registros, por loja e total da rede. Linhas sem loja_id entram
 * SOMENTE no total (não há coluna para atribuí-las).
 */
export function aggregatePerdas(rows: PerdaAggRow[]): PerdasByLoja {
  const byLoja = new Map<number, PerdasAggregate>();
  const total: PerdasAggregate = { valor: 0, itens: 0 };
  for (const row of rows) {
    const valor = row.valor_estimado ?? 0;
    total.valor += valor;
    total.itens += 1;
    if (row.loja_id == null) continue;
    let agg = byLoja.get(row.loja_id);
    if (!agg) {
      agg = { valor: 0, itens: 0 };
      byLoja.set(row.loja_id, agg);
    }
    agg.valor += valor;
    agg.itens += 1;
  }
  return { byLoja, total };
}

/** Linha mínima de `notas_fiscais` necessária à agregação de compras. */
export interface NotaAggRow {
  loja_id: number | null;
  valor_total: number | null;
}

/** Resultado da agregação de compras (NFs): por loja + total da rede. */
export interface ComprasByLoja {
  byLoja: Map<number, number>;
  /** Total da REDE — NFs com loja_id NULL entram SOMENTE aqui. */
  total: number;
}

/**
 * Agrega compras (NFs) do período: soma de `valor_total` por loja + total
 * da rede ("gasto até hoje"). NFs sem loja_id entram SOMENTE no total —
 * documentado no contrato (não há coluna para atribuí-las).
 */
export function aggregateCompras(rows: NotaAggRow[]): ComprasByLoja {
  const byLoja = new Map<number, number>();
  let total = 0;
  for (const row of rows) {
    const valor = row.valor_total ?? 0;
    total += valor;
    if (row.loja_id == null) continue;
    byLoja.set(row.loja_id, (byLoja.get(row.loja_id) ?? 0) + valor);
  }
  return { byLoja, total };
}

/** Linha do feed de movimentações (nome do produto já resolvido no fetch). */
export interface MovementFeedRow {
  loja_id: number | null;
  tipo_movimentacao: string;
  data_movimentacao: string | null;
  quantidade: number | null;
  produtoNome: string;
}

/** Converte uma linha crua do feed em {@link TvRecentMove} exibível. */
export function mapFeedRow(row: MovementFeedRow): TvRecentMove {
  return {
    hora: timeHHMMFromIso(row.data_movimentacao),
    timestamp: row.data_movimentacao,
    tipo: row.tipo_movimentacao,
    produtoNome: row.produtoNome,
    quantidade: row.quantidade ?? 0,
  };
}

/**
 * Agrupa o feed (já ordenado DESC por `data_movimentacao` na query) por
 * loja, mantendo as `perStore` primeiras linhas de cada uma (mini-feed
 * "AGORA"). Linhas sem loja são ignoradas. NÃO reordena — confia na
 * ordenação da query (única fonte do "mais recente primeiro").
 */
export function buildRecentMoves(
  rows: MovementFeedRow[],
  perStore: number = TV_MINI_FEED_SIZE,
): Map<number, TvRecentMove[]> {
  const out = new Map<number, TvRecentMove[]>();
  for (const row of rows) {
    if (row.loja_id == null) continue;
    let list = out.get(row.loja_id);
    if (!list) {
      list = [];
      out.set(row.loja_id, list);
    }
    if (list.length >= perStore) continue;
    list.push(mapFeedRow(row));
  }
  return out;
}

