async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
  // 1) Último dia com dado para a loja
  const { data: latest, error: latestErr } = await supabase
    .from('historico_vendas')
    .select('data')
    .eq('loja_id', lojaId)
    .order('data', { ascending: false })
    .limit(1);
  if (latestErr) throw latestErr;
  const refDate = latest?.[0]?.data;
  if (!refDate) return null;

  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));

  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
  //    comparativo PRINCIPAL v3; mesma semana = secundário)
  const [curRes, weekRes, dayRes] = await Promise.all([
    supabase
      .from('historico_vendas')
      .select('valor_total, quantidade')
      .eq('loja_id', lojaId)
      .eq('data', refDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', weekAgoDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', dayBeforeDate)
      .limit(2000),
  ]);
  if (curRes.error) throw curRes.error;
  if (weekRes.error) throw weekRes.error;
  if (dayRes.error) throw dayRes.error;

  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
  const quantidade = (curRes.data ?? []).reduce(
    (s, r) => s + (r.quantidade ?? 0),
    0,
  );
  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
    const list = rows ?? [];
    return list.length > 0
      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
      : null;
  };

  return {
    lojaId,
    dataReferencia: refDate,
    valor,
    quantidade,
    valorSemanaAnterior: sumOrNull(weekRes.data),
    valorDiaAnterior: sumOrNull(dayRes.data),
  };
}

