// ─────────────────────────────────────────────────────────────────────────────
// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
// passada (secundário) — uma única query em degust_vendas_diarias
// ─────────────────────────────────────────────────────────────────────────────

interface DegustReferenceSales {
  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
  yesterday: Map<number, number>;
  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
  lastWeek: Map<number, number>;
}

async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
  const yesterday = new Map<number, number>();
  const lastWeek = new Map<number, number>();
  const ids = [...ctx.degustLojaIds];
  if (ids.length === 0) return { yesterday, lastWeek };
  const now = new Date();
  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('degust_vendas_diarias')
      .select('loja_id, valor_total, data')
      .in('data', [yesterdayDate, lastWeekDate])
      .in('loja_id', ids)
      .order('id')
      .range(from, to),
  );
  for (const row of rows) {
    const target = row.data === yesterdayDate ? yesterday : lastWeek;
    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
  }
  return { yesterday, lastWeek };
