// ─────────────────────────────────────────────────────────────────────────────
// Feed nomeado de movimentações de hoje (mini-feed "AGORA" por coluna)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Quantas linhas o feed busca de uma vez. NÃO pagina de propósito: é um
 * feed "AGORA" (últimas {@link TV_MINI_FEED_SIZE} por unidade) — query
 * separada dos AGREGADOS (que seguem paginados via fetchAllPages). Em dia
 * de pico (>150 movimentações) uma unidade parada há muitas horas pode
 * ficar sem mini-feed — aceitável: o card já mostra "última bipagem".
 */
const TV_FEED_FETCH_LIMIT = 150;

/** Forma da linha de `movimentacoes` com o join de nome do produto. */
interface MovementFeedQueryRow {
  loja_id: number | null;
  tipo_movimentacao: string;
  data_movimentacao: string | null;
  quantidade: number | null;
  produto_master: { nome: string } | null;
}

function toFeedRows(rows: MovementFeedQueryRow[]): MovementFeedRow[] {
  // Feed mostra TODA movimentação (evento operacional aconteceu, produto
  // ativo ou não) — diferente das listas de produto, que filtram ativo=true.
  return rows.map((r) => ({
    loja_id: r.loja_id,
    tipo_movimentacao: r.tipo_movimentacao,
    data_movimentacao: r.data_movimentacao,
    quantidade: r.quantidade,
    produtoNome: r.produto_master?.nome ?? '(sem produto)',
  }));
}

async function fetchMovementFeed(): Promise<Map<number, TvRecentMove[]>> {
  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);
  const { data, error } = await supabase
    .from('movimentacoes')
    .select(
      'loja_id, tipo_movimentacao, data_movimentacao, quantidade, produto_master:produtos_master(nome)',
    )
    .gte('data_movimentacao', startOfDay.toISOString())
    .order('data_movimentacao', { ascending: false })
    .limit(TV_FEED_FETCH_LIMIT);
  if (error) throw error;
  return buildRecentMoves(toFeedRows(data ?? []), TV_MINI_FEED_SIZE);
}

// ─────────────────────────────────────────────────────────────────────────────
// Perdas no período do filtro global (tabela `perdas`)
// ─────────────────────────────────────────────────────────────────────────────

/** Par período corrente + período anterior equivalente (comparativo). */
export interface PeriodedAggregates<T> {
  current: T;
  previous: T;
}

async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
  const bounds = rangeToLocalDayBounds(range);
  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('perdas')
      .select('loja_id, valor_estimado')
      .gte('data_identificacao', bounds.startIso)
      .lt('data_identificacao', bounds.endExclusiveIso)
      .order('id')
      .range(from, to),
  );
  return aggregatePerdas(rows);
}

async function fetchPerdasAggregates(
  period: TvPeriod,
): Promise<PeriodedAggregates<PerdasByLoja>> {
  const now = new Date();
  const [current, previous] = await Promise.all([
    loadPerdasRange(periodRange(period, now)),
    loadPerdasRange(previousPeriodRange(period, now)),
  ]);
  return { current, previous };
}

// ─────────────────────────────────────────────────────────────────────────────
// Compras no período do filtro global (notas_fiscais — "gasto até hoje")
// ─────────────────────────────────────────────────────────────────────────────

async function loadComprasRange(range: TvDateRange): Promise<ComprasByLoja> {
  // Campo de data canônico: `data_nota` (emissão) — mesmo critério do DRE.
  // Status válido = tudo menos `erro` (NF_COUNTED_STATUSES); transferências
  // internas "Momma Doces" excluídas (não são compra). Paginado: um mês de
  // NFs pode passar de 1000 linhas.
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('notas_fiscais')
      .select('loja_id, valor_total')
      .gte('data_nota', range.from)
      .lte('data_nota', range.to)
      .in('status', [...NF_COUNTED_STATUSES])
      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
      .order('id')
      .range(from, to),
  );
  return aggregateCompras(rows);
}

async function fetchComprasAggregates(
  period: TvPeriod,
): Promise<PeriodedAggregates<ComprasByLoja>> {
  const now = new Date();
  const [current, previous] = await Promise.all([
    loadComprasRange(periodRange(period, now)),
    loadComprasRange(previousPeriodRange(period, now)),
  ]);
  return { current, previous };
}

