/**
 * @module features/tv-dashboard/model/useTvStoreDetail
 *
 * Drill-down por loja (`/tv/loja/:id`) com filtro de data PRÓPRIO
 * (range custom {from,to} em dias locais):
 * - KPIs no range (vendas, perdas, compras, contagens de movimentações)
 *   com comparativo vs range ANTERIOR de mesma duração;
 * - listas: perdas detalhadas, NFs de compra, estoque crítico completo,
 *   feed de movimentações (até {@link TV_DETAIL_FEED_LIMIT}, mais recente 1º).
 *
 * Compartilha cache com o painel: contexto (lojas/canais) e estoque crítico
 * usam as MESMAS query keys do `useTvDashboardData`.
 *
 * Decisões herdadas do painel:
 * - vendas: Degust → `degust_vendas_diarias`; demais → `historico_vendas`
 *   (fábrica não vende → 0);
 * - compras: campo canônico `data_nota`, status válido ≠ erro, sem
 *   transferências "Momma Doces"; NFs com loja_id NULL nunca aparecem aqui
 *   (entram só no total da rede do hero);
 * - agregados potencialmente >1000 linhas paginam via `fetchAllPages`.
 */

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type {
  TvComprasSummary,
  TvCriticalItem,
  TvDateRange,
  TvNotaFiscalDetail,
  TvPerdaDetail,
  TvPerdasSummary,
  TvRecentMove,
  TvSalesChannel,
} from './types';
import {
  TV_DETAIL_FEED_LIMIT,
  aggregateMovements,
  aggregatePerdas,
  buildStockSummary,
  fetchAllPages,
  mapFeedRow,
  previousRangeSameDuration,
  rangeToLocalDayBounds,
  relativeDelta,
  sortCriticalItems,
} from './tvMath';
import {
  NF_COUNTED_STATUSES,
  NF_TRANSFER_SUPPLIER_PATTERN,
  TV_QUERY_INTERVALS,
  fetchStockAlerts,
  fetchTvContext,
  tvDashboardKeys,
  type TvContext,
} from './useTvDashboardData';

// ─────────────────────────────────────────────────────────────────────────────
// Fetch consolidado do detalhe (1 queryFn, sub-fetches em paralelo)
// ─────────────────────────────────────────────────────────────────────────────

interface MovementCounts {
  entradas: number;
  saidas: number;
}

interface StoreDetailPayload {
  vendas: { valor: number; previous: number };
  perdas: { valor: number; itens: number; previousValor: number };
  compras: { valor: number; previousValor: number };
  movimentos: { current: MovementCounts; previous: MovementCounts };
  perdasList: TvPerdaDetail[];
  notasList: TvNotaFiscalDetail[];
  feed: TvRecentMove[];
}

async function loadVendasRange(
  isDegust: boolean,
  lojaId: number,
  range: TvDateRange,
): Promise<number> {
  // Degust = degust_vendas_diarias (linha-por-produto/dia: um mês pode
  // passar de 1000 linhas → paginar); Linx = historico_vendas (idem).
  const table = isDegust ? 'degust_vendas_diarias' : 'historico_vendas';
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from(table)
      .select('valor_total')
      .eq('loja_id', lojaId)
      .gte('data', range.from)
      .lte('data', range.to)
      .order('id')
      .range(from, to),
  );
  return rows.reduce((s, r) => s + (r.valor_total ?? 0), 0);
}

interface PerdaDetailQueryRow {
  id: number;
  quantidade: number | null;
  unidade: string | null;
  motivo_perda: string;
  valor_estimado: number | null;
  data_identificacao: string | null;
  produto_nome_perda: string | null;
  produto_master: { nome: string } | null;
}

async function loadPerdasDetail(
  lojaId: number,
  range: TvDateRange,
): Promise<{ valor: number; itens: number; list: TvPerdaDetail[] }> {
  const bounds = rangeToLocalDayBounds(range);
  const rows = await fetchAllPages<PerdaDetailQueryRow>((from, to) =>
    supabase
      .from('perdas')
      .select(
        'id, quantidade, unidade, motivo_perda, valor_estimado, data_identificacao, produto_nome_perda, produto_master:produtos_master(nome)',
      )
      .eq('loja_id', lojaId)
      .gte('data_identificacao', bounds.startIso)
      .lt('data_identificacao', bounds.endExclusiveIso)
      .order('id')
      .range(from, to),
  );
  const list: TvPerdaDetail[] = rows
    .map((r) => ({
      id: r.id,
      // Nome via join produtos_master; fallback pro texto livre da perda
      produtoNome: r.produto_master?.nome ?? r.produto_nome_perda ?? '(sem produto)',
      quantidade: r.quantidade ?? 0,
      unidade: r.unidade,
      motivo: r.motivo_perda,
      valor: r.valor_estimado ?? 0,
      data: r.data_identificacao,
    }))
    // Mais recente primeiro (nulls de data por último)
    .sort((a, b) => (b.data ?? '').localeCompare(a.data ?? ''));
  return {
    valor: list.reduce((s, p) => s + p.valor, 0),
    itens: list.length,
    list,
  };
}

async function loadPerdasAggregate(
  lojaId: number,
  range: TvDateRange,
): Promise<number> {
  const bounds = rangeToLocalDayBounds(range);
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('perdas')
      .select('loja_id, valor_estimado')
      .eq('loja_id', lojaId)
      .gte('data_identificacao', bounds.startIso)
      .lt('data_identificacao', bounds.endExclusiveIso)
      .order('id')
      .range(from, to),
  );
  return aggregatePerdas(rows).total.valor;
}

interface NotaDetailQueryRow {
  id: number;
  numero_nota: string;
  fornecedor: string;
  valor_total: number | null;
  data_nota: string;
}

function notasQueryRange(lojaId: number, range: TvDateRange) {
  return (from: number, to: number) =>
    supabase
      .from('notas_fiscais')
      .select('id, numero_nota, fornecedor, valor_total, data_nota')
      .eq('loja_id', lojaId)
      .gte('data_nota', range.from)
      .lte('data_nota', range.to)
      .in('status', [...NF_COUNTED_STATUSES])
      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
      .order('id')
      .range(from, to);
}

async function loadNotasDetail(
  lojaId: number,
  range: TvDateRange,
): Promise<{ valor: number; list: TvNotaFiscalDetail[] }> {
  const rows = await fetchAllPages<NotaDetailQueryRow>(notasQueryRange(lojaId, range));
  const list: TvNotaFiscalDetail[] = rows
    .map((r) => ({
      id: r.id,
      numero: r.numero_nota,
      fornecedor: r.fornecedor,
      valor: r.valor_total ?? 0,
      dataNota: r.data_nota,
    }))
    .sort((a, b) => b.dataNota.localeCompare(a.dataNota));
  return { valor: list.reduce((s, n) => s + n.valor, 0), list };
}

async function loadNotasAggregate(
  lojaId: number,
  range: TvDateRange,
): Promise<number> {
  const rows = await fetchAllPages<NotaDetailQueryRow>(notasQueryRange(lojaId, range));
  return rows.reduce((s, r) => s + (r.valor_total ?? 0), 0);
}

async function loadMovementCounts(
  lojaId: number,
  range: TvDateRange,
): Promise<MovementCounts> {
  const bounds = rangeToLocalDayBounds(range);
  // Volume real ~380 movimentações/dia (pico >1k): um mês passa FÁCIL de
  // 1000 linhas — paginação obrigatória no agregado.
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('movimentacoes')
      .select('loja_id, tipo_movimentacao, data_movimentacao')
      .eq('loja_id', lojaId)
      .gte('data_movimentacao', bounds.startIso)
      .lt('data_movimentacao', bounds.endExclusiveIso)
      .order('id')
      .range(from, to),
  );
  const agg = aggregateMovements(rows).get(lojaId);
  return { entradas: agg?.entradas ?? 0, saidas: agg?.saidas ?? 0 };
}

async function loadFeed(lojaId: number, range: TvDateRange): Promise<TvRecentMove[]> {
  const bounds = rangeToLocalDayBounds(range);
  // Feed do drill-down: query separada com join de nome, SEM paginação
  // (cap intencional em TV_DETAIL_FEED_LIMIT — mais recente primeiro).
  const { data, error } = await supabase
    .from('movimentacoes')
    .select(
      'loja_id, tipo_movimentacao, data_movimentacao, quantidade, produto_master:produtos_master(nome)',
    )
    .eq('loja_id', lojaId)
    .gte('data_movimentacao', bounds.startIso)
    .lt('data_movimentacao', bounds.endExclusiveIso)
    .order('data_movimentacao', { ascending: false })
    .limit(TV_DETAIL_FEED_LIMIT);
  if (error) throw error;
  return (data ?? []).map((r) =>
    mapFeedRow({
      loja_id: r.loja_id,
      tipo_movimentacao: r.tipo_movimentacao,
      data_movimentacao: r.data_movimentacao,
      quantidade: r.quantidade,
      produtoNome: r.produto_master?.nome ?? '(sem produto)',
    }),
  );
}

async function fetchStoreDetail(
  ctx: TvContext,
  lojaId: number,
  range: TvDateRange,
): Promise<StoreDetailPayload> {
  const previous = previousRangeSameDuration(range);
  const isDegust = ctx.degustLojaIds.has(lojaId);

  const [
    vendasCur,
    vendasPrev,
    perdasCur,
    perdasPrevValor,
    notasCur,
    notasPrevValor,
    movsCur,
    movsPrev,
    feed,
  ] = await Promise.all([
    loadVendasRange(isDegust, lojaId, range),
    loadVendasRange(isDegust, lojaId, previous),
    loadPerdasDetail(lojaId, range),
    loadPerdasAggregate(lojaId, previous),
    loadNotasDetail(lojaId, range),
    loadNotasAggregate(lojaId, previous),
    loadMovementCounts(lojaId, range),
    loadMovementCounts(lojaId, previous),
    loadFeed(lojaId, range),
  ]);

  return {
    vendas: { valor: vendasCur, previous: vendasPrev },
    perdas: {
      valor: perdasCur.valor,
      itens: perdasCur.itens,
      previousValor: perdasPrevValor,
    },
    compras: { valor: notasCur.valor, previousValor: notasPrevValor },
    movimentos: { current: movsCur, previous: movsPrev },
    perdasList: perdasCur.list,
    notasList: notasCur.list,
    feed,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────────────────────

/** Retorno do {@link useTvStoreDetail}. */
export interface TvStoreDetailData {
  lojaId: number | null;
  /** Nome da loja (null enquanto o contexto não carregou / id inválido). */
  nome: string | null;
  /** Canal de venda da loja (live/defasado/fábrica), ou null sem contexto. */
  channel: TvSalesChannel | null;
  /** Range aplicado (eco do parâmetro, para rótulos). */
  range: TvDateRange;
  /** Range anterior de mesma duração usado nos comparativos. */
  previousRange: TvDateRange;
  /** Vendas somadas no range + delta vs range anterior. */
  vendas: { valor: number; deltaPct: number | null };
  perdas: TvPerdasSummary;
  compras: TvComprasSummary;
  /** Contagens de movimentações no range + delta do TOTAL (entr+saídas). */
  movimentos: {
    entradas: number;
    saidas: number;
    total: number;
    deltaPct: number | null;
  };
  /** Perdas detalhadas no range (mais recente primeiro). */
  perdasList: TvPerdaDetail[];
  /** NFs de compra da loja no range (mais recente primeiro). */
  notasList: TvNotaFiscalDetail[];
  /** Estoque crítico COMPLETO da loja (ordenado por severidade). */
  criticalItems: TvCriticalItem[];
  /** Feed de movimentações nomeado (até 50, mais recente primeiro). */
  feed: TvRecentMove[];
  isLoading: boolean;
  isError: boolean;
}

const EMPTY_SUMMARY = { valor: 0, deltaPct: null } as const;

/**
 * Drill-down de uma loja com range custom. `lojaId` null desabilita as
 * queries (página ainda resolvendo o param da rota). Estoque crítico vem da
 * MESMA query do painel (cache compartilhado — estado ATUAL, não recortado
 * pelo range). Realtime de perdas/movimentações invalida via prefixo
 * `storeDetailRoot` no {@link useTvRealtime}.
 */
export function useTvStoreDetail(
  lojaId: number | null,
  range: TvDateRange,
): TvStoreDetailData {
  const ctxQuery = useQuery({
    queryKey: tvDashboardKeys.context(),
    queryFn: fetchTvContext,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });
  const ctx = ctxQuery.data;

  const stockQuery = useQuery({
    queryKey: tvDashboardKeys.stock(),
    queryFn: fetchStockAlerts,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
    enabled: lojaId != null,
  });

  const detailQuery = useQuery({
    queryKey:
      lojaId != null
        ? tvDashboardKeys.storeDetail(lojaId, range)
        : ([...tvDashboardKeys.storeDetailRoot(), 'disabled'] as const),
    queryFn: () => {
      if (!ctx || lojaId == null) {
        throw new Error('tv-store-detail: contexto/loja ausentes');
      }
      return fetchStoreDetail(ctx, lojaId, range);
    },
    enabled: lojaId != null && !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  return useMemo<TvStoreDetailData>(() => {
    const previousRange = previousRangeSameDuration(range);
    const loja = lojaId != null ? ctx?.lojas.find((l) => l.id === lojaId) : undefined;
    const channel: TvSalesChannel | null = !ctx || lojaId == null
      ? null
      : ctx.factoryLojaId === lojaId
        ? 'factory'
        : ctx.degustLojaIds.has(lojaId)
          ? 'degust-live'
          : 'linx-lagged';

    const detail = detailQuery.data;
    const stockDetail =
      lojaId != null
        ? buildStockSummary(stockQuery.data ?? []).get(lojaId)
        : undefined;

    const movsCur = detail?.movimentos.current ?? { entradas: 0, saidas: 0 };
    const movsPrev = detail?.movimentos.previous ?? { entradas: 0, saidas: 0 };
    const totalCur = movsCur.entradas + movsCur.saidas;
    const totalPrev = movsPrev.entradas + movsPrev.saidas;

    return {
      lojaId,
      nome: loja?.nome ?? null,
      channel,
      range,
      previousRange,
      vendas: detail
        ? {
            valor: detail.vendas.valor,
            deltaPct: relativeDelta(detail.vendas.valor, detail.vendas.previous),
          }
        : EMPTY_SUMMARY,
      perdas: detail
        ? {
            valor: detail.perdas.valor,
            itens: detail.perdas.itens,
            deltaPct: relativeDelta(detail.perdas.valor, detail.perdas.previousValor),
          }
        : { ...EMPTY_SUMMARY, itens: 0 },
      compras: detail
        ? {
            valor: detail.compras.valor,
            deltaPct: relativeDelta(detail.compras.valor, detail.compras.previousValor),
          }
        : EMPTY_SUMMARY,
      movimentos: {
        entradas: movsCur.entradas,
        saidas: movsCur.saidas,
        total: totalCur,
        deltaPct: relativeDelta(totalCur, totalPrev > 0 ? totalPrev : null),
      },
      perdasList: detail?.perdasList ?? [],
      notasList: detail?.notasList ?? [],
      criticalItems: sortCriticalItems(stockDetail?.itens ?? []),
      feed: detail?.feed ?? [],
      isLoading:
        ctxQuery.isLoading || (lojaId != null && detailQuery.isLoading),
      isError: ctxQuery.isError || detailQuery.isError,
    };
  }, [
    lojaId,
    range,
    ctx,
    ctxQuery.isLoading,
    ctxQuery.isError,
    stockQuery.data,
    detailQuery.data,
    detailQuery.isLoading,
    detailQuery.isError,
  ]);
}

