/**
 * Subscreve `postgres_changes` em movimentações/estoque/alertas e invalida
 * as queries relevantes do painel TV:
 * - `movimentacoes` → heartbeat de movimentações (+ expedições da fábrica);
 * - `estoque` / `alertas_estoque` → alertas de estoque (faixa de exceções).
 *
 * Remove os canais e cancela timers pendentes ao desmontar.
 */
export function useTvRealtime(): void {
  const queryClient = useQueryClient();
  // Timers por grupo de invalidação (debounce independente)
  const movementTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const stockTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const invalidateMovements = () => {
      if (movementTimer.current) return; // já agendado nesta janela
      movementTimer.current = setTimeout(() => {
        movementTimer.current = null;
        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.movements() });
      }, REALTIME_DEBOUNCE_MS);
    };

    const invalidateStock = () => {
      if (stockTimer.current) return;
