// ─────────────────────────────────────────────────────────────────────────────
// v3 — filtro global de período, deltas genéricos, crítico nomeado, feed
// ─────────────────────────────────────────────────────────────────────────────

describe('periodRange', () => {
  // qui 04/06/2026 (junho/2026 começa numa segunda)
  const now = at(14);

  it('today: hoje → hoje', () => {
    expect(periodRange('today', now)).toEqual({
      from: '2026-06-04',
      to: '2026-06-04',
    });
  });

  it('week: segunda da semana corrente → hoje', () => {
    expect(periodRange('week', now)).toEqual({
      from: '2026-06-01',
      to: '2026-06-04',
    });
  });

  it('week: na própria segunda, range de 1 dia', () => {
    const monday = new Date(2026, 5, 1, 9);
    expect(periodRange('week', monday)).toEqual({
      from: '2026-06-01',
      to: '2026-06-01',
    });
  });

  it('week: domingo pertence à semana iniciada na segunda ANTERIOR', () => {
    const sunday = new Date(2026, 5, 7, 12); // dom 07/06/2026
    expect(periodRange('week', sunday)).toEqual({
      from: '2026-06-01',
      to: '2026-06-07',
    });
  });

  it('month: dia 1º do mês corrente → hoje', () => {
    expect(periodRange('month', now)).toEqual({
      from: '2026-06-01',
      to: '2026-06-04',
    });
  });
});

describe('previousPeriodRange', () => {
  const now = at(14); // qui 04/06/2026

  it('today: ontem → ontem', () => {
    expect(previousPeriodRange('today', now)).toEqual({
      from: '2026-06-03',
      to: '2026-06-03',
    });
  });

  it('today: 1º do mês volta pro último dia do mês anterior', () => {
    const first = new Date(2026, 5, 1, 8);
    expect(previousPeriodRange('today', first)).toEqual({
      from: '2026-05-31',
      to: '2026-05-31',
    });
  });

  it('week: semana passada até o MESMO dia da semana', () => {
    expect(previousPeriodRange('week', now)).toEqual({
      from: '2026-05-25',
      to: '2026-05-28',
    });
  });

  it('month: mês passado do dia 1º até o MESMO dia', () => {
    expect(previousPeriodRange('month', now)).toEqual({
      from: '2026-05-01',
      to: '2026-05-04',
    });
  });

  it('month: clampa ao fim do mês anterior mais curto (31/05 → 30/04)', () => {
    const may31 = new Date(2026, 4, 31, 10);
    expect(previousPeriodRange('month', may31)).toEqual({
      from: '2026-04-01',
      to: '2026-04-30',
    });
  });

  it('month: 30/03 clampa pra 28/02 (fevereiro não bissexto)', () => {
    const mar30 = new Date(2026, 2, 30, 10);
    expect(previousPeriodRange('month', mar30)).toEqual({
      from: '2026-02-01',
      to: '2026-02-28',
    });
  });

  it('month: janeiro volta pra dezembro do ano anterior', () => {
    const jan15 = new Date(2026, 0, 15, 10);
    expect(previousPeriodRange('month', jan15)).toEqual({
      from: '2025-12-01',
      to: '2025-12-15',
    });
  });
});

describe('previousRangeSameDuration', () => {
  it('range de 1 dia volta 1 dia', () => {
    expect(
      previousRangeSameDuration({ from: '2026-06-04', to: '2026-06-04' }),
    ).toEqual({ from: '2026-06-03', to: '2026-06-03' });
  });

  it('range de 7 dias volta os 7 dias imediatamente anteriores', () => {
    expect(
      previousRangeSameDuration({ from: '2026-06-01', to: '2026-06-07' }),
    ).toEqual({ from: '2026-05-25', to: '2026-05-31' });
  });

  it('cruza fronteira de mês sem buraco nem overlap', () => {
    const prev = previousRangeSameDuration({ from: '2026-06-01', to: '2026-06-04' });
    expect(prev).toEqual({ from: '2026-05-28', to: '2026-05-31' });
  });
});

describe('rangeToLocalDayBounds', () => {
  it('início = 00:00 local do from; fim EXCLUSIVO = 00:00 do dia após o to', () => {
    const { startIso, endExclusiveIso } = rangeToLocalDayBounds({
      from: '2026-06-04',
      to: '2026-06-04',
    });
    expect(new Date(startIso).getTime()).toBe(new Date(2026, 5, 4).getTime());
    expect(new Date(endExclusiveIso).getTime()).toBe(new Date(2026, 5, 5).getTime());
  });
});

describe('relativeDelta', () => {
  it('calcula % vs base positiva', () => {
    expect(relativeDelta(110, 100)).toBeCloseTo(10, 5);
    expect(relativeDelta(80, 100)).toBeCloseTo(-20, 5);
  });

  it('base ausente/zero/negativa → null (sem número inventado)', () => {
    expect(relativeDelta(100, null)).toBeNull();
    expect(relativeDelta(100, undefined)).toBeNull();
    expect(relativeDelta(100, 0)).toBeNull();
    expect(relativeDelta(100, -5)).toBeNull();
  });

  it('weekOverWeekDelta delega pro mesmo cálculo', () => {
    expect(weekOverWeekDelta(110, 100)).toBe(relativeDelta(110, 100));
  });
});

describe('proRataDayBase (generalização do proRataLastWeekBase)', () => {
  it('pró-rateia QUALQUER dia de referência pela fração da janela', () => {
    // 16h = metade da janela 10-22 → base 1000 vira 500
    expect(proRataDayBase(1000, at(16))).toBeCloseTo(500, 5);
  });

  it('antes da abertura → null (sem ponto de comparação honesto)', () => {
    expect(proRataDayBase(1000, at(8))).toBeNull();
  });

  it('base ausente/não positiva → null', () => {
    expect(proRataDayBase(null, at(16))).toBeNull();
    expect(proRataDayBase(0, at(16))).toBeNull();
  });

  it('proRataLastWeekBase (alias histórico) devolve o mesmo resultado', () => {
    expect(proRataLastWeekBase(1000, at(16))).toBe(proRataDayBase(1000, at(16)));
  });
});

describe('sortCriticalItems', () => {
  const item = (
    produtoNome: string,
    quantidade: number,
    quantidadeMinima: number,
    zerado: boolean,
  ) => ({ produtoNome, quantidade, quantidadeMinima, zerado });

  it('zerados primeiro, depois abaixo do mínimo por % faltante desc', () => {
    const sorted = sortCriticalItems([
      item('QUASE-OK', 9, 10, false), // 10% faltante
      item('ZERADO', 0, 5, true),
      item('METADE', 5, 10, false), // 50% faltante
    ]);
    expect(sorted.map((i) => i.nome)).toEqual(['ZERADO', 'METADE', 'QUASE-OK']);
    expect(sorted[0].severity).toBe('zerado');
    expect(sorted[1].severity).toBe('abaixo-minimo');
  });

  it('empate de % faltante desempata por nome (pt-BR, estável)', () => {
    const sorted = sortCriticalItems([
      item('BANANA', 5, 10, false),
      item('AÇAÍ', 5, 10, false),
    ]);
    expect(sorted.map((i) => i.nome)).toEqual(['AÇAÍ', 'BANANA']);
  });

  it('entre zerados, quantidade mais negativa primeiro (fração maior)', () => {
    const sorted = sortCriticalItems([
      item('ZERO', 0, 10, true),
      item('NEGATIVO', -5, 10, true),
    ]);
    expect(sorted.map((i) => i.nome)).toEqual(['NEGATIVO', 'ZERO']);
  });

  it('mapeia campos pro contrato {nome, quantidade, minima, severity}', () => {
    const [c] = sortCriticalItems([item('BROWNIE', 2, 8, false)]);
    expect(c).toEqual({
      nome: 'BROWNIE',
      quantidade: 2,
      minima: 8,
      severity: 'abaixo-minimo',
    });
  });
});

describe('aggregatePerdas', () => {
  it('agrega R$ e itens por loja + total da rede', () => {
    const { byLoja, total } = aggregatePerdas([
      { loja_id: 2, valor_estimado: 50 },
      { loja_id: 2, valor_estimado: 30 },
      { loja_id: 4, valor_estimado: 20 },
    ]);
    expect(byLoja.get(2)).toEqual({ valor: 80, itens: 2 });
    expect(byLoja.get(4)).toEqual({ valor: 20, itens: 1 });
    expect(total).toEqual({ valor: 100, itens: 3 });
  });

  it('valor_estimado null conta 0 em R$ mas SOMA no nº de itens', () => {
    const { byLoja, total } = aggregatePerdas([
      { loja_id: 2, valor_estimado: null },
      { loja_id: 2, valor_estimado: 10 },
    ]);
    expect(byLoja.get(2)).toEqual({ valor: 10, itens: 2 });
    expect(total.itens).toBe(2);
  });

  it('linha sem loja_id entra SOMENTE no total da rede', () => {
    const { byLoja, total } = aggregatePerdas([
      { loja_id: null, valor_estimado: 99 },
    ]);
    expect(byLoja.size).toBe(0);
    expect(total).toEqual({ valor: 99, itens: 1 });
  });
});

describe('aggregateCompras', () => {
  it('soma valor_total por loja + total da rede', () => {
    const { byLoja, total } = aggregateCompras([
      { loja_id: 1, valor_total: 1000 },
      { loja_id: 1, valor_total: 500 },
      { loja_id: 3, valor_total: 200 },
    ]);
    expect(byLoja.get(1)).toBe(1500);
    expect(byLoja.get(3)).toBe(200);
    expect(total).toBe(1700);
  });

  it('NF sem loja_id entra SOMENTE no total da rede (documentado)', () => {
    const { byLoja, total } = aggregateCompras([
      { loja_id: null, valor_total: 300 },
      { loja_id: 2, valor_total: 100 },
    ]);
    expect(byLoja.size).toBe(1);
    expect(byLoja.get(2)).toBe(100);
    expect(total).toBe(400);
  });
});

describe('buildRecentMoves / mapFeedRow / timeHHMMFromIso', () => {
  const move = (
    loja_id: number | null,
    hourIso: string,
    tipo = 'entrada',
    quantidade: number | null = 2,
    produtoNome = 'BROWNIE',
