import { createElement, type ReactNode } from 'react';
import { renderHook, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { describe, it, expect, vi } from 'vitest';
import { useTvStoreDetail } from './useTvStoreDetail';

// Mock leve do client Supabase (mesmo padrão do useTvDashboardData.test):
// builder encadeável thenable que resolve sempre { data: [], error: null }.
vi.mock('@/integrations/supabase/client', () => {
  type QueryResult = { data: never[]; error: null };
  const CHAIN_METHODS = [
    'select',
    'eq',
    'gt',
    'gte',
    'lt',
    'lte',
    'in',
    'or',
    'is',
    'not',
    'order',
    'limit',
    'range',
  ] as const;

  const makeBuilder = (): Record<string, unknown> => {
    const builder: Record<string, unknown> = {};
    for (const method of CHAIN_METHODS) {
      builder[method] = () => builder;
    }
    builder.then = (onFulfilled: (value: QueryResult) => unknown) =>
      Promise.resolve({ data: [] as never[], error: null }).then(onFulfilled);
    return builder;
  };

  return {
    supabase: {
      from: () => makeBuilder(),
      functions: {
        invoke: async () => ({ data: { flash: [] }, error: null }),
      },
    },
  };
});

function createWrapper() {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return ({ children }: { children: ReactNode }) =>
    createElement(QueryClientProvider, { client }, children);
}

const RANGE = { from: '2026-06-01', to: '2026-06-04' };

describe('useTvStoreDetail', () => {
  it('monta detalhe vazio sem crash (loja sem dados no range)', async () => {
    const { result, unmount } = renderHook(() => useTvStoreDetail(4, RANGE), {
      wrapper: createWrapper(),
    });

    await waitFor(() => expect(result.current.isLoading).toBe(false));

    expect(result.current.isError).toBe(false);
    expect(result.current.lojaId).toBe(4);
    // Contexto vazio no mock → loja desconhecida (nome/canal honestamente null)
    expect(result.current.nome).toBeNull();
    expect(result.current.channel).toBe('linx-lagged');
    // KPIs zerados sem delta inventado
    expect(result.current.vendas).toEqual({ valor: 0, deltaPct: null });
    expect(result.current.perdas).toEqual({ valor: 0, itens: 0, deltaPct: null });
    expect(result.current.compras).toEqual({ valor: 0, deltaPct: null });
    expect(result.current.movimentos).toEqual({
      entradas: 0,
      saidas: 0,
      total: 0,
      deltaPct: null,
    });
    // Listas vazias explícitas (estado vazio, nunca undefined)
    expect(result.current.perdasList).toEqual([]);
    expect(result.current.notasList).toEqual([]);
    expect(result.current.criticalItems).toEqual([]);
    expect(result.current.feed).toEqual([]);
    // Range ecoado + anterior de MESMA duração (4 dias → 28-31/05)
    expect(result.current.range).toEqual(RANGE);
    expect(result.current.previousRange).toEqual({
      from: '2026-05-28',
      to: '2026-05-31',
    });

    unmount();
  });

  it('lojaId null desabilita as queries (página resolvendo o param)', async () => {
    const { result, unmount } = renderHook(
      () => useTvStoreDetail(null, RANGE),
      { wrapper: createWrapper() },
    );
    await waitFor(() => expect(result.current.isLoading).toBe(false));
    expect(result.current.lojaId).toBeNull();
    expect(result.current.nome).toBeNull();
    expect(result.current.channel).toBeNull();
    expect(result.current.vendas.valor).toBe(0);
    unmount();
  });
});
